program='''from collections import deque

def components(grid, color):
    h, w = len(grid), len(grid[0])
    seen = set()
    result = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != color or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == color and (yy,xx) not in seen:
                        seen.add((yy,xx)); q.append((yy,xx))
            result.append(cells)
    return result

def transform(grid):
    out = [row[:] for row in grid]
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(row.count(v) for row in grid))
    marker = 0 if any(0 in row for row in grid) else 9
    # The marker elbow is the color of the long, bent divider.
    for color in set(v for row in grid for v in row) - {bg}:
        cells = [p for comp in components(grid, color) for p in comp]
        if len(cells) > 3:
            rr = [r for r,c in cells]; cc = [c for r,c in cells]
            if max(rr)-min(rr) >= 3 and max(cc)-min(cc) >= 3:
                marker = color
    comps = components(grid, 2)
    if comps:
        for r,c in max(comps, key=len): out[r][c] = marker
    return out
'''
